    expect(getValue(postsPostResponse, "errors.0.id"), 'error id').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getValue(postsPostResponse, "errors.1"), 'single error').toBeUndefined();
